files.content:
terraform {
  required_version = ">= 1.5.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.63.0, < 7.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = local.tags
  }
}

variable "aws_region" {
  type        = string
  description = "AWS Region selected by the immutable Architecture Document."
  default     = "us-east-1"
}

variable "event_sns_fanout_consumer_primary_artifact_path" {
  type        = string
  description = "Stable relative package output produced by the separate Prompt 32A workload builder."
  default     = "../application/artifacts/workload_event_sns_fanout_consumer_primary/function.zip"
  validation {
    condition     = can(regex("^\\.\\.?/", var.event_sns_fanout_consumer_primary_artifact_path))
    error_message = "Package path must be repository-relative and begin with ./ or ../; absolute machine paths are forbidden."
  }
}

variable "event_sns_fanout_consumer_secondary_artifact_path" {
  type        = string
  description = "Stable relative package output produced by the separate Prompt 32A workload builder."
  default     = "../application/artifacts/workload_event_sns_fanout_consumer_secondary/function.zip"
  validation {
    condition     = can(regex("^\\.\\.?/", var.event_sns_fanout_consumer_secondary_artifact_path))
    error_message = "Package path must be repository-relative and begin with ./ or ../; absolute machine paths are forbidden."
  }
}

variable "stage" {
  type        = string
  description = "Architecture variable stage."
  default     = "test"
}

locals {
  tags = {
    CloudMarkupArchitecture     = "architecture_event_multi"
    CloudMarkupRevision         = "revision_event_sns_fanout_consumer_primary_1"
    CloudMarkupSolutionRevision = "solution_event_multi_revision_1"
    ManagedBy                   = "CloudMarkup"
  }
}

resource "aws_lambda_function" "event_sns_fanout_consumer_primary" {
  function_name                  = "event_sns_fanout_consumer_primary"
  description                    = "CloudMarkup notes-API workload."
  role                           = aws_iam_role.notes_role.arn
  handler                        = "index.handler"
  runtime                        = "nodejs24.x"
  architectures                  = ["arm64"]
  memory_size                    = 256
  reserved_concurrent_executions = 10
  timeout                        = 30
  filename                       = var.event_sns_fanout_consumer_primary_artifact_path
  source_code_hash               = filebase64sha256(var.event_sns_fanout_consumer_primary_artifact_path)
  tracing_config {
    mode = "Active"
  }
  environment {
    variables = {
      "APP_STAGE" = var.stage
    }
  }
  tags = local.tags
}

resource "aws_lambda_function" "event_sns_fanout_consumer_secondary" {
  function_name                  = "event_sns_fanout_consumer_secondary"
  description                    = "CloudMarkup notes-API workload."
  role                           = aws_iam_role.secondary_role.arn
  handler                        = "index.handler"
  runtime                        = "nodejs24.x"
  architectures                  = ["arm64"]
  memory_size                    = 256
  reserved_concurrent_executions = 10
  timeout                        = 30
  filename                       = var.event_sns_fanout_consumer_secondary_artifact_path
  source_code_hash               = filebase64sha256(var.event_sns_fanout_consumer_secondary_artifact_path)
  tracing_config {
    mode = "Active"
  }
  environment {
    variables = {
      "APP_STAGE" = var.stage
    }
  }
  tags = local.tags
}

data "aws_iam_policy_document" "event_logs_policy_sns_fanout_multi_1" {
  statement {
    sid       = "eventlogspolicysnsfanoutmulti1"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = [format("%s:*", aws_cloudwatch_log_group.event_logs_sns_fanout_multi_1.arn)]
  }
}

data "aws_iam_policy_document" "event_logs_policy_sns_fanout_multi_2" {
  statement {
    sid       = "eventlogspolicysnsfanoutmulti2"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = [format("%s:*", aws_cloudwatch_log_group.event_logs_sns_fanout_multi_2.arn)]
  }
}

data "aws_iam_policy_document" "secondary_trust_policy" {
  statement {
    sid     = "secondarytrustpolicy"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "trust_policy" {
  statement {
    sid     = "trustpolicy"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "event_logs_policy_sns_fanout_multi_1" {
  name   = "event_logs_policy_sns_fanout_multi_1"
  role   = aws_iam_role.notes_role.name
  policy = data.aws_iam_policy_document.event_logs_policy_sns_fanout_multi_1.json
}

resource "aws_iam_role_policy" "event_logs_policy_sns_fanout_multi_2" {
  name   = "event_logs_policy_sns_fanout_multi_2"
  role   = aws_iam_role.secondary_role.name
  policy = data.aws_iam_policy_document.event_logs_policy_sns_fanout_multi_2.json
}

resource "aws_lambda_permission" "primary_sns_permission" {
  statement_id  = "primarysnspermission"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.event_sns_fanout_consumer_primary.function_name
  principal     = "sns.amazonaws.com"
  source_arn    = aws_sns_topic.fanout.arn
}

resource "aws_lambda_permission" "secondary_sns_permission" {
  statement_id  = "secondarysnspermission"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.event_sns_fanout_consumer_secondary.function_name
  principal     = "sns.amazonaws.com"
  source_arn    = aws_sns_topic.fanout.arn
}

resource "aws_sns_topic" "fanout" {
  name                        = "image-events"
  fifo_topic                  = false
  content_based_deduplication = false
  kms_master_key_id           = "alias/aws/sns"
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}

resource "aws_sns_topic_subscription" "primary_subscription" {
  topic_arn            = aws_sns_topic.fanout.arn
  protocol             = "lambda"
  endpoint             = aws_lambda_function.event_sns_fanout_consumer_primary.arn
  raw_message_delivery = false
}

resource "aws_sns_topic_subscription" "secondary_subscription" {
  topic_arn            = aws_sns_topic.fanout.arn
  protocol             = "lambda"
  endpoint             = aws_lambda_function.event_sns_fanout_consumer_secondary.arn
  raw_message_delivery = false
}

resource "aws_cloudwatch_log_group" "event_logs_sns_fanout_multi_1" {
  name              = "/aws/lambda/notes_handler"
  log_group_class   = "STANDARD"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}

resource "aws_cloudwatch_log_group" "event_logs_sns_fanout_multi_2" {
  name              = "/aws/lambda/secondary_handler"
  log_group_class   = "STANDARD"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}
